<script setup lang="ts">
import type { ApiSuccess, SessionPayload } from '~/types/api'
import { apiErrorMessage } from '~/utils/api-error'

definePageMeta({layout:'dashboard',middleware:'auth'})
useHead({title:'Matériel IT'})
type Asset={id:string;inventoryTag:string;type:string;brand:string|null;model:string|null;serialNumber:string|null;status:string;assignedUserId:string|null;location:string|null;purchaseDate:string|null;warrantyUntil:string|null;notes:string|null;updatedAt:string}
type UserOption={id:string;firstName:string;lastName:string;email:string}
const route=useRoute();const id=computed(()=>String(route.params.id))
const {data:session}=await useFetch<ApiSuccess<SessionPayload>>('/api/auth/me',{key:'session-me'})
const permissions=computed(()=>session.value?.data.user.permissions??[]);const canWrite=computed(()=>permissions.value.includes('*')||permissions.value.includes('it:write'))
const {data,error,refresh}=await useFetch<ApiSuccess<Asset>>(()=>`/api/assets/${id.value}`);const asset=computed(()=>data.value?.data??null)
const {data:usersData}=await useFetch<ApiSuccess<UserOption[]>>('/api/assets/users',{immediate:canWrite.value});const users=computed(()=>usersData.value?.data??[])
const form=reactive({inventoryTag:'',type:'',brand:'',model:'',serialNumber:'',status:'STOCK',assignedUserId:'',location:'',purchaseDate:'',warrantyUntil:'',notes:''});const saving=ref(false);const errorMessage=ref('');const successMessage=ref('')
watch(asset,(value)=>{if(!value)return;form.inventoryTag=value.inventoryTag;form.type=value.type;form.brand=value.brand||'';form.model=value.model||'';form.serialNumber=value.serialNumber||'';form.status=value.status;form.assignedUserId=value.assignedUserId||'';form.location=value.location||'';form.purchaseDate=value.purchaseDate?value.purchaseDate.slice(0,10):'';form.warrantyUntil=value.warrantyUntil?value.warrantyUntil.slice(0,10):'';form.notes=value.notes||''},{immediate:true})
async function save(){if(!canWrite.value||saving.value)return;saving.value=true;errorMessage.value='';successMessage.value='';try{await $fetch(`/api/assets/${id.value}`,{method:'PUT',body:{...form,assignedUserId:form.assignedUserId||null,purchaseDate:form.purchaseDate||null,warrantyUntil:form.warrantyUntil||null}});await refresh();successMessage.value='Matériel mis à jour.'}catch(error){errorMessage.value=apiErrorMessage(error,'Le matériel n’a pas pu être mis à jour.')}finally{saving.value=false}}
</script>
<template><div><div class="page-head"><div><h1>{{ asset?.inventoryTag||'Matériel' }}</h1><p v-if="asset">{{ [asset.brand,asset.model].filter(Boolean).join(' ')||asset.type }}</p></div><NuxtLink class="btn btn-secondary" to="/dashboard/assets">Retour au parc</NuxtLink></div><div v-if="errorMessage" class="alert alert-error" style="margin-bottom:18px">{{ errorMessage }}</div><div v-if="successMessage" class="alert alert-success" style="margin-bottom:18px">{{ successMessage }}</div><div v-if="error" class="alert alert-error">Impossible de charger ce matériel.</div><form v-else-if="asset&&canWrite" class="card card-pad" @submit.prevent="save"><div class="form-grid"><div class="field"><label for="asset-tag">Référence *</label><input id="asset-tag" v-model="form.inventoryTag" class="input" required maxlength="100"></div><div class="field"><label for="asset-type">Type *</label><input id="asset-type" v-model="form.type" class="input" required maxlength="100"></div><div class="field"><label for="asset-brand">Marque</label><input id="asset-brand" v-model="form.brand" class="input" maxlength="100"></div><div class="field"><label for="asset-model">Modèle</label><input id="asset-model" v-model="form.model" class="input" maxlength="150"></div><div class="field"><label for="asset-serial">Numéro de série</label><input id="asset-serial" v-model="form.serialNumber" class="input" maxlength="150"></div><div class="field"><label for="asset-status">Statut</label><select id="asset-status" v-model="form.status" class="select"><option value="STOCK">En stock</option><option value="ASSIGNED">Affecté</option><option value="MAINTENANCE">Maintenance</option><option value="RETIRED">Retiré</option><option value="LOST">Perdu</option></select></div><div class="field"><label for="asset-user">Affecté à</label><select id="asset-user" v-model="form.assignedUserId" class="select"><option value="">Personne</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.firstName }} {{ user.lastName }} — {{ user.email }}</option></select></div><div class="field"><label for="asset-location">Localisation</label><input id="asset-location" v-model="form.location" class="input" maxlength="200"></div><div class="field"><label for="asset-purchase">Achat</label><input id="asset-purchase" v-model="form.purchaseDate" class="input" type="date"></div><div class="field"><label for="asset-warranty">Garantie</label><input id="asset-warranty" v-model="form.warrantyUntil" class="input" type="date"></div><div class="field field-full"><label for="asset-notes">Notes</label><textarea id="asset-notes" v-model="form.notes" class="textarea" rows="5" /></div></div><button class="btn btn-primary" type="submit" style="margin-top:18px" :disabled="saving">{{ saving?'Enregistrement…':'Enregistrer' }}</button></form><section v-else-if="asset" class="card card-pad"><span class="badge">{{ asset.status }}</span><h2>{{ asset.inventoryTag }}</h2><p>{{ [asset.brand,asset.model].filter(Boolean).join(' ')||asset.type }}</p><p>{{ asset.location||'Localisation non renseignée' }}</p></section></div></template>
